def main():
    assert set(P.keys()) == set(IDS), (sorted(P.keys()), IDS)
    assert len(P) == 20
    OUT.mkdir(parents=True, exist_ok=True)
    for cid in IDS:
        (OUT / f"{cid}.json").write_text(json.dumps(P[cid], ensure_ascii=False, indent=2), encoding="utf-8")
    print("wrote", len(P))

if __name__ == "__main__":
    main()
